(defn- parse [s]
  (if (str/blank? s) {}
      (into {} (map (fn [kv] (let [i (str/index-of kv "=")] [(subs kv 0 i) (subs kv (inc i))]))
                    (str/split s #"\|")))))
(def ^:private parsed (atom {}))
(defn- table* [id]
  (or (get @parsed id)
      (let [spec (get raw id)
            t (into {:separator (:separator spec)}
                    (for [k [:languages :countries :scripts :variants]] [k (parse (get spec k ""))]))
            ;; ROOT holds only what differs from en, a country table only what
            ;; differs from its language's; a name it lacks is written as its code
            base (cond (= id "") "en" (:parent spec) (:parent spec))
            t (if base
                (merge-with (fn [a b] (if (map? a) (into {} (remove (fn [[k v]] (= k v)) (merge a b))) b)) (table* base) t)
                t)]
        (swap! parsed assoc id t)
        t)))
;; Chinese by region: Taiwan writes Traditional, Hong Kong and Macao the Hong
;; Kong Traditional, the rest Simplified (CLDR's parent locales)
(def ^:private aliases
  {"zh-TW" "zh-Hant" "zh-Hant-TW" "zh-Hant" "zh-HK" "zh-Hant-HK" "zh-MO" "zh-Hant-HK" "zh-Hant-MO" "zh-Hant-HK"})
(defn- display-id
  "The table a display locale id reads: itself (or its alias), then each id it
  narrows to by dropping its last subtag, else ROOT."
  [id]
  (loop [id id]
    (let [id (get aliases id id)]
      (cond (contains? raw id) id
            (str/includes? id "-") (recur (subs id 0 (str/last-index-of id "-")))
            :else ""))))
(defn names [id] (table* (display-id id)))
